UPDATE `lfgdungeons` SET `name_kokr` = '저주받은 기사', `name_frfr` = 'Le Cavalier sans tête', `name_dede` = 'Der Kopflose Reiter', `name_zhcn` = '无头骑士', `name_zhtw` = '無頭騎士', `name_eses` = 'El Jinete decapitado', `name_esmx` = 'El Jinete decapitado', `name_ruru` = 'Всадник без головы', `tooltip_kokr` = '아제로스 마을이 전부 불타버리기 전에 광기에 찬, 저주받은 기사를 물리쳐야 합니다.', `tooltip_frfr` = 'Vaincre le Cavalier sans tête avant qu\'il brûle jusqu\'au dernier village en Azeroth.', `tooltip_dede` = 'Bezwingt den wahnsinnigen Kopflosen Reiter, bevor er jede Siedlung Azeroths niederbrennt.', `tooltip_zhcn` = '在疯狂的无头骑士烧毁艾泽拉斯的每一座村庄之前击败他。', `tooltip_zhtw` = '在瘋狂的無頭騎士將艾澤拉斯的每一座建築都燒毀之前將他擊敗。', `tooltip_eses` = 'Derrota al demente Jinete decapitado antes de que queme hasta el último cimiento de Azeroth.', `tooltip_esmx` = 'Derrota al demente Jinete decapitado antes de que queme hasta el último cimiento de Azeroth.', `tooltip_ruru` = 'Победите одержимого Всадника без головы, прежде чем он сожжет все поселения в Азероте.' WHERE `id` = 285;
UPDATE `lfgdungeons` SET `name_kokr` = '서리 군주 아훈', `name_frfr` = 'Le seigneur du Givre Ahune', `name_dede` = 'Frostfürst Ahune', `name_zhcn` = '冰霜之王埃霍恩', `name_zhtw` = '冰霜領主艾胡恩', `name_eses` = 'El Señor de la Escarcha Ahune', `name_esmx` = 'El Señor de la Escarcha Ahune', `name_ruru` = 'Повелитель Холода Ахун', `tooltip_kokr` = '서리 군주가 아제로스에 완전히 나타나 여름을 영원히 사라지게 하기 전에 처치해야 합니다.', `tooltip_frfr` = 'Vaincre Ahune, le seigneur du Givre, avant qu\'il se manifeste entièrement en Azeroth et qu\'il mette fin à l\'été à tout jamais.', `tooltip_dede` = 'Bezwingt Ahune den Frostfürsten, bevor er sich vollständig auf Azeroth manifestiert und dem Sommer auf ewig ein Ende setzt.', `tooltip_zhcn` = '在冰霜之王埃霍恩将艾泽拉斯的夏日永久终结之前击败它。', `tooltip_zhtw` = '在冰霜領主艾胡恩完全在艾澤拉斯上顯現並永遠終結夏日之前將他擊敗。', `tooltip_eses` = 'Derrota a Ahune, Señor de la Escarcha, antes de que se manifieste en Azeroth y acabe con el verano.', `tooltip_esmx` = 'Derrota a Ahune, Señor de la Escarcha, antes de que se manifieste en Azeroth y acabe con el verano.', `tooltip_ruru` = 'Победите Ахуна, Повелителя Холода, прежде чем он появится в Азероте и навсегда положит конец лету.' WHERE `id` = 286;
